#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

int main() {
    int linesCount;
    std::cin >> linesCount;
    std::cin.ignore(); // ignore the newline after the integer input
    std::string fullLine;
    std::getline(std::cin, fullLine);

    // Split the string by parentheses using a simple approach
    std::vector<std::string> splitParts;
    size_t start = 0, end = 0;
    while ((end = fullLine.find('(', start)) != std::string::npos) {
        if (end > start) {
            splitParts.push_back(fullLine.substr(start, end - start));
        }
        start = end + 1;
        end = fullLine.find(')', start);
        if (end != std::string::npos) {
            splitParts.push_back(fullLine.substr(start, end - start));
            start = end + 1;
        }
    }
    if (start < fullLine.size()) {
        splitParts.push_back(fullLine.substr(start));
    }

    int maxLengthFound = 0;
    for (const auto& part : splitParts) {
        size_t pos = 0;
        size_t prev = 0;
        while ((pos = part.find('_', prev)) != std::string::npos) {
            std::string token = part.substr(prev, pos - prev);
            maxLengthFound = std::max(static_cast<int>(token.length()), maxLengthFound);
            prev = pos + 1;
        }
        // last token after the last underscore
        std::string token = part.substr(prev);
        maxLengthFound = std::max(static_cast<int>(token.length()), maxLengthFound);
    }

    std::vector<std::string> insideParentheses;
    int startIdx = -1;
    for (size_t i = 0; i < fullLine.size(); ++i) {
        if (fullLine[i] == '(') {
            startIdx = i;
        } else if (fullLine[i] == ')' && startIdx != -1) {
            insideParentheses.push_back(fullLine.substr(startIdx + 1, i - startIdx - 1));
            startIdx = -1;
        }
    }

    int totalWordsCount = 0;
    for (const auto& segment : insideParentheses) {
        size_t prev = 0, pos;
        while ((pos = segment.find('_', prev)) != std::string::npos) {
            if (pos > prev) {
                totalWordsCount++;
            }
            prev = pos + 1;
        }
        if (prev < segment.size()) {
            totalWordsCount++;
        }
    }

    std::cout << maxLengthFound << " " << totalWordsCount << std::endl;
    return 0;
}
